contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account, uint256 /* seed */) public view {
        require(true);
        // Read-only invariant probing over the public surface for arbitrary accounts.
        (bool okV, bytes memory retV) = address(c).staticcall(
            abi.encodeWithSignature("latestVersion(address)", account)
        );
        require(okV);
        uint256 accountVersion = abi.decode(retV, (uint256));

        uint256 productVersion = c.latestVersion();

        (bool okP, bytes memory retP) = address(c).staticcall(
            abi.encodeWithSignature("position(address)", account)
        );
        require(okP);
        (UFixed18 maker, UFixed18 taker) = abi.decode(
            retP, (UFixed18, UFixed18)
        );

        bool doubleSided = (UFixed18.unwrap(maker) > 0) && (UFixed18.unwrap(taker) > 0);

        // General rules that must hold for every account at any point in time:
        //  1. An account's settled version can never run ahead of the product's version.
        //  2. A settled position is never double-sided (maker and taker both nonzero).
        assert(accountVersion <= productVersion && !doubleSided);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOracle) public {
        // Capture the oracle before the attempt (view call).
        address before = address(c.oracle());

        // Only the product's coordinator owner may update the oracle; the test
        // contract is not the owner, so the call must revert and have no effect.
        bool reverted;
        try c.updateOracle(IOracleProvider(newOracle)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address after = address(c.oracle());
        assert(reverted && after == before);
    }
}

