contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account) public {
        require(true);

        // Read initial (fresh) state through the public surface
        uint256 versionBefore = c.latestVersion();
        uint256 accountVersionBefore = c.latestVersion(account);
        Position memory posBefore = c.position(account);
        bool liquidatingBefore = c.isLiquidating(account);
        bool closedBefore = c.closed();

        // settle() needs controller()/oracle(); on a fresh product these are unset
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }

        // Read post-call state
        uint256 versionAfter = c.latestVersion();
        uint256 accountVersionAfter = c.latestVersion(account);
        Position memory posAfter = c.position(account);
        bool liquidatingAfter = c.isLiquidating(account);
        bool closedAfter = c.closed();

        assert(
            reverted
            && versionBefore == 0 && versionAfter == 0
            && accountVersionBefore == 0 && accountVersionAfter == 0
            && posBefore.maker == UFixed18.wrap(0) && posBefore.taker == UFixed18.wrap(0)
            && posAfter.maker == UFixed18.wrap(0) && posAfter.taker == UFixed18.wrap(0)
            && !liquidatingBefore && !liquidatingAfter
            && !closedBefore && !closedAfter
        );
    }

    receive() external payable {}
}

