    function run(string calldata nameStr, string calldata symbolStr) public {
        require(bytes(nameStr).length > 0);
        require(bytes(nameStr).length <= 32);
        require(bytes(symbolStr).length <= 32);

        PayoffDefinition memory pd;
        pd.payoffType = PayoffDefinitionLib.PayoffType(0);
        pd.payoffDirection = PayoffDefinitionLib.PayoffDirection(0);

        IProduct.ProductInfo memory info;
        info.name = nameStr;
        info.symbol = symbolStr;
        info.payoffDefinition = pd;
        info.oracle = IOracleProvider(address(uint160(1)));
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);

        bool reverted;
        try c.initialize(info) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            assert(keccak256(bytes(c.name())) == keccak256(bytes(nameStr)) &&
                   keccak256(bytes(c.symbol())) == keccak256(bytes(symbolStr)));
        } else {
            assert(true);
        }
    }
